    @classmethod
    @lru_cache(1024 * 16)
    def _split_cells(cls, segment: "Segment", cut: int) -> Tuple["Segment", "Segment"]:
        text, style, control = segment
        if not text or cut <= 0:
            return Segment("", style, control), Segment("", style, control)

        before_text = ""
        current_length = 0
        split_index = len(text) # Default to splitting after the last character if cut is large enough

        for i, char in enumerate(text):
            char_len = cell_size(char)
            potential_length = current_length + char_len

            if potential_length > cut:
                # Split before this character (at index i)
                split_index = i
                break

            current_length = potential_length
            before_text += char
        else:
            # Loop finished without breaking (cut is greater than or equal to total length)
            split_index = len(text)


        return Segment(text[:split_index], style, control), \
               Segment(text[split_index:], style, control)
